<?php $pageTitle='User Management';require '../includes/admin-header.php';$pdo=db();$action=$_GET['action']??'';$id=(int)($_GET['id']??0);if($action==='toggle'&&$id){$pdo->prepare("UPDATE users SET status=IF(status='active','blocked','active') WHERE id=?")->execute([$id]);flash('success','User status updated.');go('admin/users.php');}if($action==='delete'&&$id){$pdo->prepare('DELETE FROM users WHERE id=?')->execute([$id]);flash('success','User deleted.');go('admin/users.php');}$users=$pdo->query('SELECT * FROM users ORDER BY created_at DESC')->fetchAll();$view=$id?$pdo->prepare('SELECT * FROM users WHERE id=?'):null;if($view){$view->execute([$id]);$view=$view->fetch();} ?>
<div class="d-flex justify-content-between mb-3"><p class="mb-0">Approve, block, edit, or remove customer accounts.</p><a class="btn btn-dark" href="add-user.php">+ Add User</a></div><?php if($view&&$action==='view'): ?><div class="alert alert-secondary"><b><?=e($view['full_name'])?></b> · <?=e($view['email'])?> · <?=e($view['mobile'])?><br><?=e($view['address'])?></div><?php endif ?><div class="card table-responsive"><table class="table align-middle mb-0"><thead><tr><th>ID</th><th>Full name</th><th>Username</th><th>Email</th><th>Mobile</th><th>Registration</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($users as $u): ?><tr><td><?=$u['id']?></td><td><?=e($u['full_name'])?></td><td><?=e($u['username'])?></td><td><?=e($u['email'])?></td><td><?=e($u['mobile'])?></td><td><?=date('d M Y',strtotime($u['created_at']))?></td><td><span class="badge <?=$u['status']==='active'?'text-bg-success':'text-bg-secondary'?>"><?=e($u['status'])?></span></td><td class="text-nowrap"><a class="btn btn-sm btn-outline-dark" href="users.php?action=view&id=<?=$u['id']?>">View</a> <a class="btn btn-sm btn-outline-dark" href="edit-user.php?id=<?=$u['id']?>">Edit</a> <a class="btn btn-sm btn-outline-<?=$u['status']==='active'?'warning':'success'?>" href="users.php?action=toggle&id=<?=$u['id']?>"><?=$u['status']==='active'?'Block':'Unblock'?></a> <a class="btn btn-sm btn-outline-danger" data-confirm="Delete this user?" href="users.php?action=delete&id=<?=$u['id']?>">Delete</a></td></tr><?php endforeach ?></tbody></table></div><?php require '../includes/admin-footer.php'; ?>
